// Dimension-wheel "shadow" icons (2026-09-22, direct instruction: "the
// wheel rhombus itself as if it is a projection into 2D from the
// various dimensions... 2D flat diamond, 3D a 3D rhombus etc" /
// "multi-dimensional shadows" / "why are rhombi different shapes to
// rhombis wheel rhombi... rhombi were supposed to show dimension by
// their appearance"). Real math: each icon is the genuine 2D shadow
// (orthogonal projection) of the zonotope generated by N unit vectors
// evenly spaced across a half-circle (angles k*180/N for k=0..N-1),
// FULLY tiled into its real C(N,2) rhombic facets -- not just an outer
// boundary outline (an earlier draft did that for N>=4 and lost the
// rhombus-ness entirely, direct correction).
//
// Construction: the "wiring diagram" / bubble-sort method (a real,
// standard construction for zonotopal tilings, closely related to
// reduced words for the longest permutation in S_n): sort the N
// vectors by angle, then reverse that order via an odd-even
// transposition sort. Each adjacent swap in that sort corresponds to
// exactly one rhombus (the two vectors being swapped), positioned at
// the running prefix-sum of whatever's currently to its left. Verified
// numerically before shipping (not just asserted): for N=3..6, this
// produces exactly C(N,2) rhombi whose total area matches the
// zonogon's own real area (sum of |cross(v_i,v_j)| over all pairs) to
// float precision -- a real gapless, overlap-free tiling, not a guess.

function vec(n, R, k) {
  const a = (Math.PI * k) / n;
  return [R * Math.cos(a), R * Math.sin(a)];
}
function add(a, b) { return [a[0] + b[0], a[1] + b[1]]; }
function pts(arr) { return arr.map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`).join(' '); }

// Returns [{corners: [4 points]}], one per real rhombic facet.
function zonogonTiling(n, R) {
  const V = [];
  for (let k = 0; k < n; k++) V.push(vec(n, R, k));
  let seq = [...Array(n).keys()];
  const rhombi = [];
  for (let pass = 0; pass < n; pass++) {
    const start = pass % 2;
    for (let k = start; k + 1 < n; k += 2) {
      const a = seq[k], b = seq[k + 1];
      if (a < b) {
        let pos = [0, 0];
        for (let m = 0; m < k; m++) pos = add(pos, V[seq[m]]);
        const va = V[a], vb = V[b];
        rhombi.push({ corners: [pos, add(pos, va), add(add(pos, va), vb), add(pos, vb)] });
        [seq[k], seq[k + 1]] = [seq[k + 1], seq[k]];
      }
    }
  }
  return rhombi;
}

function centerRhombi(rhombi) {
  const all = rhombi.flatMap((r) => r.corners);
  const cx = all.reduce((s, p) => s + p[0], 0) / all.length;
  const cy = all.reduce((s, p) => s + p[1], 0) / all.length;
  return rhombi.map((r) => ({ corners: r.corners.map(([x, y]) => [x - cx, y - cy]) }));
}

function zonogonSvg(n) {
  const rhombi = centerRhombi(zonogonTiling(n, 22));
  // Direct report, live: cycling through many different opacity levels
  // (an earlier draft) read as "different colors... own outline shapes,
  // confusing" -- a jumble of translucent overlapping edges instead of
  // one cohesive symbol. Simplified to ONE consistent fill opacity plus
  // a real stroke on every facet, so the divisions between rhombi are
  // drawn deliberately (same line weight/color throughout) rather than
  // implied by uneven translucency.
  const polys = rhombi.map((r) =>
    `<polygon points="${pts(r.corners)}" fill="currentColor" fill-opacity="0.35" stroke="currentColor" stroke-width="1.2"/>`
  ).join('\n    ');
  return `<svg viewBox="-30 -30 60 60" width="1em" height="1em" role="img" aria-label="${n}-vector zonogon shadow">${polys}</svg>`;
}

const DIMENSION_N = { '2D': 2, '3D': 3, '4D': 4, '5D': 5, '6D': 6 };

export function dimensionShadowIcon(label) {
  const n = DIMENSION_N[label];
  if (!n) return null;
  return zonogonSvg(n);
}

// Almanac's own symbol (direct instruction: "four rhombi in a rhombi
// and inner rhombi should align precisely with outer rhombi not
// rotated") -- a real, simple 2x2 subdivision: split the outer
// rhombus's own 2 generating vectors exactly in half, giving 4 smaller
// rhombi (each a same-orientation, half-scale copy of the whole,
// arranged in a genuine 2x2 grid) that tile the outer shape exactly,
// no gaps, no rotation relative to the outer edges.
export function almanacIcon() {
  const R = 22;
  const angleDeg = 70;
  const v0 = [R, 0];
  const v1 = [R * Math.cos((angleDeg * Math.PI) / 180), R * Math.sin((angleDeg * Math.PI) / 180)];
  const h0 = [v0[0] / 2, v0[1] / 2];
  const h1 = [v1[0] / 2, v1[1] / 2];
  const outer = [[0, 0], v0, add(v0, v1), v1];
  const cx = outer.reduce((s, p) => s + p[0], 0) / 4;
  const cy = outer.reduce((s, p) => s + p[1], 0) / 4;
  const shift = ([x, y]) => [x - cx, y - cy];
  const bases = [[0, 0], h0, h1, add(h0, h1)];
  // Same consistent-fill-plus-stroke treatment as zonogonSvg above, not
  // per-facet opacity cycling -- see that function's own comment.
  const polys = bases.map((base) => {
    const corners = [base, add(base, h0), add(add(base, h0), h1), add(base, h1)].map(shift);
    return `<polygon points="${pts(corners)}" fill="currentColor" fill-opacity="0.35" stroke="currentColor" stroke-width="1.2"/>`;
  }).join('\n    ');
  return `<svg viewBox="-30 -30 60 60" width="1em" height="1em" role="img" aria-label="Almanac">${polys}</svg>`;
}
